public class InnerClusterInstanceFleetResizingSpecificationsFactory(Action<Humidifier.EMR.ClusterTypes.InstanceFleetResizingSpecifications> factoryAction = null) : SubResourceFactory<Humidifier.EMR.ClusterTypes.InstanceFleetResizingSpecifications>
{

    internal InnerClusterOnDemandResizingSpecificationFactory OnDemandResizeSpecificationFactory { get; set; }

    internal InnerClusterSpotResizingSpecificationFactory SpotResizeSpecificationFactory { get; set; }

    protected override Humidifier.EMR.ClusterTypes.InstanceFleetResizingSpecifications Create()
    {
        var instanceFleetResizingSpecificationsResult = CreateInstanceFleetResizingSpecifications();
        factoryAction?.Invoke(instanceFleetResizingSpecificationsResult);

        return instanceFleetResizingSpecificationsResult;
    }

    private Humidifier.EMR.ClusterTypes.InstanceFleetResizingSpecifications CreateInstanceFleetResizingSpecifications()
    {
        var instanceFleetResizingSpecificationsResult = new Humidifier.EMR.ClusterTypes.InstanceFleetResizingSpecifications();

        return instanceFleetResizingSpecificationsResult;
    }
    public override void CreateChildren(Humidifier.EMR.ClusterTypes.InstanceFleetResizingSpecifications result)
    {
        base.CreateChildren(result);

        result.OnDemandResizeSpecification ??= OnDemandResizeSpecificationFactory?.Build();
        result.SpotResizeSpecification ??= SpotResizeSpecificationFactory?.Build();
    }

} // End Of Class

